INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv16lwnzke8l', 'course-bili-bv16lwnzke8l', '100001', '0', 'BILI-PRO-006', 'course-category-programming', 'instructor-bili-359151217', 'go语言桌面端开发|wails零基础入门教程', '22 讲完整课程 · 2 小时 21 分钟', 'Wails是一个开源项目，旨在让开发者能够使用Go和Web技术（如React、Vue等）来构建桌面应用。它提供了一种轻量级且高效的解决方案，相比传统的Electron框架，Wails构建的应用具有更小的体积和更快的启动速', '课程简介：Wails是一个开源项目，旨在让开发者能够使用Go和Web技术（如React、Vue等）来构建桌面应用。它提供了一种轻量级且高效的解决方案，相比传统的Electron框架，Wails构建的应用具有更小的体积和更快的启动速度。课程结构：共 3 章 22 讲，累计时长 2 小时 21 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立完整的编程知识框架，理解语言核心语法与运行机制","通过真实案例掌握调试、重构与工程化协作方法","独立完成课程配套项目，形成可写进简历的作品集","具备继续进阶框架、算法与系统设计的学习路径"]', '["零基础转行开发的初学者","需要系统补齐基础的在职开发者","希望掌握第二门语言的工程师"]', '["能熟练使用电脑与浏览器","具备基础的逻辑思维与英文文档阅读习惯"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/25d3a4db9c4513897c5de116879347b03fc383fe.jpg', '["编程开发","零基础","实战项目","go语言桌面端开发","wails零基础入门教程"]', 8481, 22, 5007, '4.3', 568, 'BV16LWnzKE8L', NULL, NULL, NULL, 1, 0, 'standard', NULL, '枫枫知道', 0, 'tenant', 'published', '2025-10-18T08:30:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
